from bisect import bisect_left
from math import inf

class ST:

	def __init__(self, arr):
		n = len(arr)
		mx = n.bit_length()
		self.st = [[0] * mx for i in range(n)]
		for i in range(n):
			self.st[i][0] = arr[i]
		for j in range(1, mx):
			for i in range(n - (1 << j) + 1):
				self.st[i][j] = max(self.st[i][j - 1], self.st[i + (1 << j - 1)][j - 1])

	def query(self, l, r):
		if l > r:
			return -inf
		s = (r + 1 - l).bit_length() - 1
		return max(self.st[l][s], self.st[r - (1 << s) + 1][s])
for i in range(int(input())):
	n = int(input())
	p = [0] + list(map(int, input().split()))
	a = [i + p[i] for i in range(n + 1)]
	st = ST(a)
	dp = [0] * (n + 1)
	last = [0] * (n + 1)
	for i in range(2, n + 1):
		if not p[i]:
			dp[i] = dp[i - 1]
			last[i] = i
			continue
		j = bisect_left(dp, i - p[i] - 1, 0, i)
		last[i] = j
		if j == i:
			dp[i] = dp[i - 1]
		else:
			dp[i] = max(dp[j], st.query(j + 1, i - 1), i - 1)
			if dp[i - 1] >= i:
				if dp[i] < max(dp[i - 1], i + p[i]):
					dp[i] = max(dp[i - 1], i + p[i])
					last[i] = i
	if dp[-1] < n:
		print('NO')
	else:
		print('YES')
		cur = n
		ans = ['R'] * n
		while cur:
			if last[cur] != cur:
				ans[cur - 1] = 'L'
				cur = last[cur]
			else:
				cur -= 1
		print(''.join(ans))
